const SW = "const C='arud-'+'__BUILD__';\nconst PRE=['/','/manifest.webmanifest','/icon.svg','/icon-192.png','/apple-touch-icon.png'];\nconst OK=p=>p==='/'||p==='/index.html'||p==='/manifest.webmanifest'||/^\\/(icon[\\w.-]*|apple-touch-icon\\.png)$/.test(p)||p==='/vendor/pdf-lib.min.js'||/^\\/(privacy|terms)(-en)?$/.test(p);\nself.addEventListener('install',e=>{e.waitUntil(caches.open(C).then(c=>c.addAll(PRE)).catch(()=>{}));self.skipWaiting();});\nself.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});\nself.addEventListener('fetch',e=>{const r=e.request,u=new URL(r.url);if(r.method!=='GET'||u.origin!==self.location.origin||!OK(u.pathname))return;\n e.respondWith(fetch(r).then(res=>{if(res.ok&&res.type==='basic'){const cp=res.clone();caches.open(C).then(c=>c.put(u.pathname==='/index.html'?'/':r,cp));}return res;}).catch(()=>caches.match(r).then(m=>m||(r.mode==='navigate'?caches.match('/'):undefined)).then(m=>m||Response.error())));});\n".replace('__BUILD__', String(BUILD));
const ICON = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"512\" height=\"512\" role=\"img\" aria-label=\"العروض والقافية\"><defs><linearGradient id=\"bg\" x1=\"0\" y1=\"0\" x2=\".35\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3e200f\"/><stop offset=\"1\" stop-color=\"#160b06\"/></linearGradient><linearGradient id=\"ch\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f7e9c4\"/><stop offset=\".55\" stop-color=\"#e2c486\"/><stop offset=\"1\" stop-color=\"#bc9654\"/></linearGradient><mask id=\"m\"><rect width=\"512\" height=\"512\" fill=\"#fff\"/><g fill=\"#000\"><rect x=\"323\" y=\"212\" width=\"22\" height=\"76\" rx=\"11\"/><rect x=\"219\" y=\"212\" width=\"22\" height=\"76\" rx=\"11\"/><rect x=\"167\" y=\"212\" width=\"22\" height=\"76\" rx=\"11\"/><rect x=\"323\" y=\"312\" width=\"22\" height=\"76\" rx=\"11\"/><rect x=\"219\" y=\"312\" width=\"22\" height=\"76\" rx=\"11\"/><rect x=\"167\" y=\"312\" width=\"22\" height=\"76\" rx=\"11\"/></g><g fill=\"none\" stroke=\"#000\" stroke-width=\"10\"><circle cx=\"282\" cy=\"250\" r=\"15\"/><circle cx=\"282\" cy=\"350\" r=\"15\"/></g></mask></defs><rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#bg)\"/><path d=\"M136 420V250A120 120 0 0 1 376 250V420Z\" fill=\"url(#ch)\" mask=\"url(#m)\"/></svg>";
