const T_CSS = ":root{--bg:#faf6ee;--card:rgba(255,255,255,.72);--tx:#2a2118;--mu:#7a6b58;--ac:#8a4b1f;--bd:#e4d8c6}@media(prefers-color-scheme:dark){:root{--bg:#120f0c;--card:rgba(32,26,21,.72);--tx:#f0e6d6;--mu:#a89883;--ac:#e0a066;--bd:#3a3026}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:17px/1.95 'Alexandria','Amiri',system-ui,serif;min-height:100vh}body::before{content:'';position:fixed;inset:0;z-index:-1;background:radial-gradient(40% 30% at 85% 5%,color-mix(in srgb,var(--ac) 22%,transparent),transparent 70%),radial-gradient(45% 35% at 5% 95%,color-mix(in srgb,var(--ac) 16%,transparent),transparent 70%)}.w{max-width:760px;margin:0 auto;padding:24px 16px 70px}h1{font-size:30px;margin:12px 0 2px;color:var(--ac)}h2{font-size:20px;margin:0 0 4px;color:var(--ac)}.s{background:var(--card);border:1px solid var(--bd);border-radius:22px;padding:16px 20px;margin:14px 0;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);animation:in .9s cubic-bezier(.22,1,.36,1) backwards}.s:nth-of-type(2){animation-delay:.05s}.s:nth-of-type(3){animation-delay:.1s}.s:nth-of-type(4){animation-delay:.15s}@keyframes in{from{opacity:0;filter:blur(12px);transform:translateY(16px)}}a{color:var(--ac)}.mu{color:var(--mu);font-size:15px}.toc{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.toc a{padding:2px 14px;border:1px solid var(--bd);border-radius:20px;text-decoration:none;font-size:14px;background:var(--card)}.top{display:flex;justify-content:space-between;align-items:center;gap:10px}.top a{text-decoration:none}ul{padding-inline-start:22px;margin:6px 0}li{margin:3px 0}table{width:100%;border-collapse:collapse;font-size:15px}td,th{border-bottom:1px dashed var(--bd);padding:6px 4px;text-align:start;vertical-align:top}th{color:var(--mu);font-weight:400}.warn{border-inline-start:4px solid var(--ac);padding:2px 12px;margin:8px 0;background:color-mix(in srgb,var(--ac) 8%,transparent);border-radius:10px}@media(prefers-reduced-motion:reduce){*{animation:none!important}}";
const TERMS = {
  ar: {
    dir: 'rtl', title: 'الشروط والأحكام والخصوصية', sub: 'آخر تحديث: 21 نوفمبر 2026', back: 'رجوع إلى الموقع', other: '<a href="/privacy-en">English</a>',
    sec: [
      ['about', 'نبذة عن الخدمة', '<p><b>نسخة تجريبية.</b> يقدّم الموقع تقطيعاً عروضياً واستخراجاً للقافية للشعر العربي، ومكتبةً للقراءة والحفظ، وخطط حفظ ومراجعة، ويستعين بالذكاء الاصطناعي في التشكيل والتصحيح وذكر القائل والموضوع وتوثيق النسبة. نتائجه قد تخطئ، ولا تصلح مرجعاً وحيداً في واجب أو بحث أو نشر، فراجعها دائماً.</p>'],
      ['accept', 'قبول الشروط', '<p>باستعمالك الموقع أو إنشاء حساب فيه فإنك توافق على هذه الشروط. فإن لم توافق فتوقف عن الاستعمال. وإن كنت قاصراً فاستعمل الخدمة بعلم وليّ أمرك.</p>'],
      ['account', 'الحساب (اختياري)', '<p>الموقع يعمل كاملاً دون حساب. وإن أنشأتَ حساباً فهدفه مزامنة <b>خطط الحفظ والإعدادات وسجل البحث والكتب التي تستوردها</b> (وتبقى الكتب المستوردة خاصة بك، ولا يراها غيرك، وتُحذف بحذف الحساب) بين أجهزتك.</p><ul><li>نخزّن معرّفك (بريد أو اسم مستخدم) واسماً اختيارياً، وكلمة سرك <b>مُشفَّرة بخوارزمية PBKDF2</b> لا نستطيع قراءتها.</li><li>لا نرسل بريداً إلكترونياً، فلا استرجاع آلي لكلمة السر. احفظها جيداً، وإن نسيتها فاطلب إعادة تعيينها من «الملاحظات» (قد نطلب ما يثبت أنك صاحب الحساب).</li><li>أنت مسؤول عن سرّية كلمة سرك وعن النشاط في حسابك.</li><li>تستطيع <b>تنزيل بياناتك أو حذف حسابك نهائياً</b> في أي وقت من صفحة الحساب، فتُحذف بياناته المخزّنة عندنا.</li><li>يجوز لنا تعليق الحسابات المسيئة أو غير النشطة.</li></ul>'],
      ['data', 'ما نجمعه وكيف نستعمله', '<table><tr><th>البيانات</th><th>الغرض</th><th>المدة والمكان</th></tr><tr><td>نصوص الأبيات عند طلب التشكيل أو التصحيح</td><td>تُرسل إلى Anthropic (Claude) لمعالجتها. لا تُدخل نصاً سرياً أو شخصياً.</td><td>تُخزَّن نتيجة كل بيت (مشكولاً) مؤقتاً حتى 90 يوماً لتسريع الطلبات وخفض التكلفة، ولا تُربط بشخصك.</td></tr><tr><td>التقطيع والقافية</td><td>يجريان في متصفحك على جهازك.</td><td>لا يُرسلان إلى أي جهة.</td></tr><tr><td>عنوان الشبكة (IP)</td><td>حساب الحدّ اليومي ومنع إساءة الاستعمال ومحاولات الدخول المتكررة.</td><td>عدّادات تُحذف بعد أيام قليلة.</td></tr><tr><td>بيانات الحساب والمزامنة</td><td>تقديم المزامنة بين أجهزتك.</td><td>حتى تحذف حسابك.</td></tr><tr><td>الملاحظات والبلاغات</td><td>مراجعتها وتحسين الخدمة (ونص البيت إن أرفقتَه وطريقة تواصل إن كتبتَها).</td><td>حتى 180 يوماً، ولا نخزّن عنوانك إلا رمزاً مجهّلاً.</td></tr><tr><td>السجل والخطط والإعدادات والمسودة</td><td>راحتك في الاستعمال.</td><td>تُحفظ في متصفحك أنت (localStorage)، ولا تصلنا إلا إن فعّلتَ المزامنة بحساب.</td></tr><tr><td>رمز الدخول ونسخ الكتب المفتوحة</td><td>يبقى الرمز (صالح 30 يوماً، ويبطل بتغيير كلمة السر) وكتبٌ فتحتَها للقراءة دون اتصال.</td><td>في متصفحك فقط، وتُمحى بتسجيل الخروج أو بمسح بيانات الموقع.</td></tr><tr><td>خط «أميري» و«Alexandria»</td><td>تحميل الخطوط من Google Fonts، فيرى مزوّدها عنوان الشبكة عند التحميل.</td><td>—</td></tr><tr><td>التحقق من أنك إنسان</td><td>قد نستعمل Cloudflare Turnstile، وهي تعالج بيانات المتصفح وفق سياستها.</td><td>—</td></tr></table><p class="warn">لا إعلانات ولا أدوات تتبّع، ولا نبيع أي بيانات.</p>'],
      ['ai', 'الذكاء الاصطناعي والمصادر', '<ul><li>التشكيل والتصحيح واسم القائل والموضوع من <b>Claude</b>، وقد تكون خاطئة؛ والتصحيح الآلي لا يعني أن النص الأصلي كان خطأً.</li><li>زر «تحقّق من المصدر» يبحث في المكتبة الشاملة عبر موصّل خارجي، وعدم الظهور لا ينفي صحة النسبة.</li><li>كل كتاب في المكتبة موسوم بحالته: <b>«مُراجَع»</b> إن دقّقه بشر، أو <b>«غير مراجَع»</b> إن استُخرج آلياً ولم يُدقَّق بعد، وقد يحتوي أخطاء في الحروف أو التشكيل.</li><li>إن وجدتَ خطأً في كتاب فاضغط «أبلغ عن خطأ» داخل القصيدة، وسنصحّحه ونحدّث الكتاب.</li></ul>'],
      ['library', 'المكتبة والمحتوى وحقوق النشر', '<ul><li>الكتب والنصوص في المكتبة محفوظة لأصحابها كلٌّ بحسب وضعه. والغرض منها <b>القراءة والحفظ الشخصي</b>، ولا يجوز إعادة نشرها أو بيعها أو استعمالها تجارياً دون إذن أصحابها.</li><li>الشعر القديم في الملك العام، أما التحقيق والتشكيل والاختيار والشرح الذي في الكتب المعاصرة فمحفوظ لأصحابه.</li><li>إن كنتَ صاحب حق وترى أن محتوى يخالف حقك فأرسل «طلب حذف» من الملاحظات، وسنزيله بعد المراجعة سريعاً.</li><li>أنت مسؤول عن حقّك في النصوص التي تُدخلها في أدوات التحليل.</li></ul>'],
      ['use', 'الاستعمال المقبول', '<ul><li>لا تحاول تعطيل الخدمة أو تجاوز حدودها أو جمع محتواها آلياً بكثافة.</li><li>لا تستعمل الحسابات أو الملاحظات لنشر محتوى مسيء أو غير قانوني.</li><li>لا تحاول الوصول إلى بيانات غيرك. والإبلاغ الأمين عن الثغرات مرحّب به.</li></ul>'],
      ['limits', 'حدود الاستعمال', '<p>للتشكيل الآلي حدّ يومي لكل جهاز وميزانية شهرية إجمالية. فإن بلغتها توقّف التشكيل الآلي مؤقتاً، ويبقى التقطيع والقافية والمكتبة تعمل.</p>'],
      ['law', 'إخلاء المسؤولية', '<p>تُقدَّم الخدمة «كما هي» دون ضمان لدقتها أو استمرارها، ولا نتحمل مسؤولية أي ضرر ناتج عن الاعتماد على نتائجها. قد نغيّر الخدمة أو نوقفها أو نعدّل هذه الشروط، وتاريخ آخر تحديث أعلى الصفحة؛ واستمرارك في الاستعمال بعد التعديل قبولٌ له.</p>'],
      ['contact', 'التواصل والإبلاغ', '<p>استعمل زر «ملاحظات» أسفل الصفحة الرئيسية أو «أبلغ عن خطأ» داخل أي بيت. لطلب حذف نتيجة نص محمي أو حذف بيانات، اكتب ذلك في ملاحظة من نوع «طلب حذف».</p>']
    ]
  },
  en: {
    dir: 'ltr', title: 'Terms, conditions & privacy', sub: 'Last updated: 21 November 2026', back: 'Back to the site', other: '<a href="/privacy">العربية</a>',
    sec: [
      ['about', 'About the service', '<p><b>Beta.</b> The site scans Arabic poetry prosodically, analyses its rhyme, offers a library for reading and memorization with study plans, and uses AI for diacritization, correction, naming the poet/topic and verifying attribution. Results can be wrong; never use them as your only reference for coursework, research or publication.</p>'],
      ['accept', 'Acceptance', '<p>By using the site or creating an account you agree to these terms. If you do not agree, stop using it. Minors should use the service with a guardian’s knowledge.</p>'],
      ['account', 'Account (optional)', '<p>The site works fully without an account. An account only syncs your <b>memorization plans, settings, search history and the books you import</b> (imported books stay private to you and are deleted with your account) across devices.</p><ul><li>We store your identifier (email or username), an optional display name, and your password <b>hashed with PBKDF2</b>; we cannot read it.</li><li>We send no email, so there is no automatic password recovery. Keep your password safe; if you lose it, request a reset via “Feedback” (we may ask for proof of ownership).</li><li>You are responsible for your password and account activity.</li><li>You can <b>download your data or permanently delete your account</b> at any time from the Account page.</li><li>We may suspend abusive or inactive accounts.</li></ul>'],
      ['data', 'What we collect and why', '<table><tr><th>Data</th><th>Purpose</th><th>Retention / where</th></tr><tr><td>Verse text when you request diacritization or correction</td><td>Sent to Anthropic (Claude) for processing. Do not enter confidential or personal text.</td><td>The result of each verse (vocalized) is cached up to 90 days to speed things up and cut cost; not linked to you.</td></tr><tr><td>Scansion and rhyme</td><td>Run in your browser, on your device.</td><td>Not sent anywhere.</td></tr><tr><td>Network address (IP)</td><td>Daily limits, abuse prevention and repeated-login throttling.</td><td>Counters deleted after a few days.</td></tr><tr><td>Account and sync data</td><td>To sync across your devices.</td><td>Until you delete your account.</td></tr><tr><td>Feedback and reports</td><td>Review and improve the service (plus the verse and optional contact you attach).</td><td>Up to 180 days; your address is kept only as an anonymised token.</td></tr><tr><td>History, plans, settings, draft</td><td>Your convenience.</td><td>Stored in your browser (localStorage); they reach us only if you enable sync with an account.</td></tr><tr><td>Login token and cached books</td><td>A token (valid 30 days, revoked when the password changes) and books you opened, for offline reading.</td><td>In your browser only; cleared on logout or when you clear site data.</td></tr><tr><td>Fonts (Amiri, Alexandria)</td><td>Loaded from Google Fonts, whose provider sees your IP.</td><td>—</td></tr><tr><td>Human check</td><td>We may use Cloudflare Turnstile, which processes browser data under Cloudflare’s policy.</td><td>—</td></tr></table><p class="warn">No ads, no tracking tools, and we sell no data.</p>'],
      ['ai', 'AI and sources', '<ul><li>Diacritics, corrections, poet and topic come from <b>Claude</b> and may be wrong; an automatic correction does not mean the original was wrong.</li><li>“Verify source” searches al-Maktaba al-Shamela through an external connector; not finding a verse does not disprove its attribution.</li><li>Every library book carries a status: <b>“Reviewed”</b> if a person proofread it, or <b>“Unreviewed”</b> if it was extracted automatically and may contain letter or diacritic errors.</li><li>If you find an error, use “Report error” inside the poem and we will correct the book.</li></ul>'],
      ['library', 'Library, content and copyright', '<ul><li>Books and texts in the library remain the property of their rights holders as applicable. They are for <b>personal reading and memorization</b>; do not republish, sell or use them commercially without permission.</li><li>Classical poetry is in the public domain; the editing, vocalization, selection and commentary of modern books are protected.</li><li>If you are a rights holder and believe content infringes your rights, send a “Deletion request” through Feedback and we will review and remove it promptly.</li><li>You are responsible for your right to the texts you enter into the analysis tools.</li></ul>'],
      ['use', 'Acceptable use', '<ul><li>Do not try to disrupt the service, bypass its limits or scrape it heavily.</li><li>Do not use accounts or feedback to post abusive or unlawful content.</li><li>Do not try to access others’ data. Good-faith vulnerability reports are welcome.</li></ul>'],
      ['limits', 'Usage limits', '<p>Automatic diacritization has a daily limit per device and an overall monthly budget. When reached, it pauses while scansion, rhyme and the library keep working.</p>'],
      ['law', 'Disclaimer', '<p>The service is provided “as is” without warranty of accuracy or availability, and we are not liable for damage resulting from reliance on its results. We may change or stop the service or amend these terms; the date above shows the latest update, and continued use means acceptance.</p>'],
      ['contact', 'Contact', '<p>Use the “Feedback” button at the bottom of the main page or “Report error” inside any verse. To request deletion of a protected text’s result or of your data, write a note of type “Deletion request”.</p>']
    ]
  }
};
function termsPage(lang) {
  const t = TERMS[lang] || TERMS.ar;
  return '<!DOCTYPE html><html lang="' + lang + '" dir="' + t.dir + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + t.title + '</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Alexandria:wght@400;600&family=Amiri&display=swap"><style>' + T_CSS + '</style></head><body><div class="w"><div class="top"><a href="/">' + (t.dir === 'rtl' ? '→ ' : '← ') + t.back + '</a>' + t.other + '</div><h1>' + t.title + '</h1><div class="mu">' + t.sub + '</div><nav class="toc">' + t.sec.map(s => '<a href="#' + s[0] + '">' + s[1] + '</a>').join('') + '</nav>' + t.sec.map(s => '<section class="s" id="' + s[0] + '"><h2>' + s[1] + '</h2>' + s[2] + '</section>').join('') + '</div></body></html>';
}
const PRIVACY = termsPage('ar'), PRIVACY_EN = termsPage('en');

