const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const png = s => !s ? new Response('Not found', { status: 404 }) : new Response(b64(s), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400', 'x-content-type-options': 'nosniff' } });

// دولار لكل مليون رمز. يمكن تجاوزها بالمتغيرين PRICE_IN وPRICE_OUT.
function prices(env, model) {
  if (env.PRICE_IN && env.PRICE_OUT) return [+env.PRICE_IN, +env.PRICE_OUT];
  if (/haiku-5-5/i.test(model)) return [0.10, 0.50];
  return [2, 10]; // Sonnet 5.5
}
const CSP = "default-src 'self'; script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com; frame-src https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self'; manifest-src 'self'; worker-src 'self'; object-src 'none'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; upgrade-insecure-requests";
const SEC_HDR = { 'strict-transport-security': 'max-age=31536000; includeSubDomains', 'x-content-type-options': 'nosniff', 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer', 'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()', 'cross-origin-opener-policy': 'same-origin', 'cross-origin-resource-policy': 'same-origin' };
function secure(res) {
  const h = new Headers(res.headers);
  for (const k in SEC_HDR) if (!h.has(k)) h.set(k, SEC_HDR[k]);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers: h });
}
