const EXPORT_MAX_AGE = 24 * 3600 * 1000;
const siteGet = async (env, n) => { const r = await env.DB.prepare('SELECT val,t FROM site WHERE name=?').bind(n).first(); if (!r) return null; try { return { ...JSON.parse(r.val), _t: r.t }; } catch (e) { return null; } };
const siteSet = (env, n, v) => env.DB.prepare('INSERT OR REPLACE INTO site(name,val,t) VALUES(?,?,?)').bind(n, JSON.stringify(v), Date.now()).run();
async function tableExists(env, name) { return !!(await env.DB.prepare("SELECT 1 AS x FROM sqlite_master WHERE type='table' AND name=?").bind(name).first()); }
async function migChecksum(m) { return (await hash(JSON.stringify([m.sql, m.alter || []]))).slice(0, 16); }

async function schemaStatus(env) {
  const have = (await tableExists(env, 'schema_migrations')) ? ((await env.DB.prepare('SELECT id,applied_at,checksum FROM schema_migrations').all()).results || []) : [];
  const out = [];
  for (const m of MIGRATIONS) { const h = have.find(x => x.id === m.id); const c = await migChecksum(m); out.push({ id: m.id, applied: !!h, at: h ? h.applied_at : null, drift: !!h && h.checksum !== c }); }
  return out;
}
async function applyMigrations(env, ip) {
  const done = [];
  for (const m of MIGRATIONS) {
    await env.DB.batch(m.sql.map(s => env.DB.prepare(s)));
    for (const [t, col] of m.alter || []) { try { await env.DB.prepare('ALTER TABLE ' + t + ' ADD COLUMN ' + col).run(); } catch (e) { /* العمود موجود */ } }
    await env.DB.prepare('INSERT OR IGNORE INTO schema_migrations(id,applied_at,checksum) VALUES(?,?,?)').bind(m.id, Date.now(), await migChecksum(m)).run();
    done.push(m.id);
  }
  await audit(env, 'schema:apply', done.join(','), ip);
  return done;
}

// ---------- وظائف الدفعات (jobs) ----------
const JOBS = {};
async function jobStart(env, kind, by) {
  const cur = await env.DB.prepare("SELECT * FROM jobs WHERE kind=? AND status IN ('queued','running') ORDER BY created DESC LIMIT 1").bind(kind).first();
  if (cur) return cur;
  const id = 'job_' + rnd(6), t = Date.now(), init = await JOBS[kind].init(env);
  await env.DB.prepare("INSERT INTO jobs(id,kind,params,status,cursor,total,done,failed,created,updated,by,log) VALUES(?,?,?,'running',?,?,0,0,?,?,?,'[]')").bind(id, kind, '{}', JSON.stringify(init.cursor), init.total, t, t, by || '').run();
  return env.DB.prepare('SELECT * FROM jobs WHERE id=?').bind(id).first();
}
async function jobStep(env, id) {
  const j = await env.DB.prepare('SELECT * FROM jobs WHERE id=?').bind(id).first();
  if (!j) throw { status: 404, error: 'no_job' };
  if (j.status !== 'running') return j;
  const cur = JSON.parse(j.cursor || '{}'), log = JSON.parse(j.log || '[]');
  const r = await JOBS[j.kind].step(env, cur, log);
  const status = r.done ? ((j.failed + (r.fail || 0)) ? 'failed' : 'done') : 'running';
  const upd = await env.DB.prepare('UPDATE jobs SET cursor=?, done=done+?, failed=failed+?, status=?, updated=?, log=? WHERE id=? AND cursor=?')
    .bind(JSON.stringify(r.cursor), r.inc || 0, r.fail || 0, status, Date.now(), JSON.stringify(log.slice(-200)), id, j.cursor).run();
  if (!(upd.meta && upd.meta.changes)) return env.DB.prepare('SELECT * FROM jobs WHERE id=?').bind(id).first(); // خطوة متزامنة أخرى سبقت: لا تكرار (العمل idempotent)
  return env.DB.prepare('SELECT * FROM jobs WHERE id=?').bind(id).first();
}

// ---------- ترحيل المكتبة: lib → sections + items (+ lib_render) ----------
// المعرّفات حتمية: sections.id = المعرف القديم؛ الكتاب bk_<id>؛ القصيدة/الباب it_<id>_<slot> حيث slot = فهرسها الأصلي (يحفظ خطط الحفظ).
// لا يكتب فوق ما حُرِّر لاحقًا: التحديث مقصور على الصفوف by='migration'.
const MIG_CHUNK = 60;
// مواضع القصائد في JSON قانوني دون تحليل الكتاب كاملًا: «{"title":» لا يمكن أن يرد داخل نص (علامات التنصيص داخل النصوص مُهرَّبة دائمًا).
// يعيد null إن لم يكن النص بالصيغة القانونية المتوقعة ⇒ الرجوع إلى JSON.parse الكامل.
function legacyPoemOffsets(data) {
  if (!data.startsWith('[{"title":') || !data.endsWith('}]')) return null;
  const pos = []; let i = 1;
  while ((i = data.indexOf('{"title":', i)) !== -1) { pos.push(i); i += 9; }
  for (let k = 1; k < pos.length; k++) if (data[pos[k] - 1] !== ',' || data[pos[k] - 2] !== '}') return null;
  return pos;
}
function legacyPoemsSlice(data, pos, from, to) {
  const out = [];
  for (let k = from; k < to; k++) {
    const a = pos[k], b = k + 1 < pos.length ? pos[k + 1] - 1 : data.length - 1;
    const o = JSON.parse(data.slice(a, b));
    if (Object.keys(o).join() !== 'title,poet,meter,verses') return null;
    out.push(o);
  }
  return out;
}
const legacyHead = r => JSON.stringify({ id: r.id, title: r.title, author: r.author, desc: r.descr, cat: r.cat || '', status: r.status || 'draft', lic: r.lic || '' });
function legacySectionOf(secs, cat) {
  if (cat && secs.some(s => s.id === cat)) return cat;
  if (!cat) { const h = secs.find(s => s.group === 'hifz'); return h ? h.id : 'other'; }
  return 'other';
}
JOBS['migrate-lib'] = {
  async init(env) { const c = await env.DB.prepare('SELECT COUNT(*) AS n FROM lib').first(); return { cursor: { i: 0, slot: 0, phase: 'sections' }, total: c ? c.n : 0 }; },
  async step(env, cur, log) {
    const t = Date.now(), secs = await getSections(env);
    if (cur.phase === 'sections') {
      const cats = ((await env.DB.prepare('SELECT DISTINCT cat FROM lib').all()).results || []).map(x => x.cat || '');
      const needOther = !secs.some(s => s.id === 'other') && cats.some(c => legacySectionOf(secs, c) === 'other');
      const all = secs.concat(needOther ? [{ id: 'other', name: 'أخرى', group: 'read', desc: '' }] : []);
      await env.DB.batch(all.map((s, k) => env.DB.prepare("INSERT INTO sections(id,parent_id,title,descr,icon,sort,status,audience,role,legacy_id,created,updated,by) VALUES(?,NULL,?,?,NULL,?,'published','all',?,?,?,?,'migration') ON CONFLICT(id) DO UPDATE SET title=excluded.title, descr=excluded.descr, sort=excluded.sort, role=excluded.role, updated=excluded.updated WHERE sections.by='migration'")
        .bind(s.id, s.name, s.desc || '', k, s.group === 'hifz' ? 'hifz' : 'read', s.id, t, t)));
      log.push({ t, ok: 'sections', n: all.length });
      return { cursor: { i: 0, slot: 0, phase: 'books' }, inc: 0 };
    }
    const ids = (await env.DB.prepare('SELECT id FROM lib ORDER BY id').all()).results || [];
    if (cur.i >= ids.length) return { cursor: cur, done: true };
    const r = await env.DB.prepare('SELECT id,title,author,descr,cat,status,lic,data,t FROM lib WHERE id=?').bind(ids[cur.i].id).first();
    const sec = legacySectionOf(secs, r.cat), group = (secs.find(s => s.id === sec) || { group: 'read' }).group;
    const kind = group === 'hifz' ? 'poem' : 'door', bid = 'bk_' + r.id, txt = r.status === 'reviewed' ? 'reviewed' : 'draft';
    const pos = legacyPoemOffsets(r.data);
    let total, chunk = null;
    if (pos) { total = pos.length; chunk = legacyPoemsSlice(r.data, pos, cur.slot, Math.min(total, cur.slot + MIG_CHUNK)); }
    if (!chunk) { const all = JSON.parse(r.data); total = all.length; chunk = all.slice(cur.slot, cur.slot + MIG_CHUNK); }
    const st = [];
    if (cur.slot === 0) st.push(env.DB.prepare("INSERT INTO items(id,section_id,parent_id,kind,kind_src,title,author,descr,lic,n_units,sort,pub_status,text_status,legacy_book,created,updated,by) VALUES(?,?,NULL,'book','migrated',?,?,?,?,?,?,'published',?,?,?,?,'migration') ON CONFLICT(id) DO UPDATE SET section_id=excluded.section_id, title=excluded.title, author=excluded.author, descr=excluded.descr, lic=excluded.lic, n_units=excluded.n_units, text_status=excluded.text_status, updated=excluded.updated WHERE items.by='migration'")
      .bind(bid, sec, r.title, r.author || '', r.descr || '', r.lic || '', total, cur.i, txt, r.id, t, t));
    const end = Math.min(total, cur.slot + MIG_CHUNK);
    for (let k = cur.slot; k < end; k++) {
      const p = chunk[k - cur.slot], body = JSON.stringify(p.verses);
      st.push(env.DB.prepare("INSERT INTO items(id,section_id,parent_id,kind,kind_src,title,poet,meter,body,body_hash,n_units,sort,slot,pub_status,text_status,legacy_book,created,updated,by) VALUES(?,?,?,?,'migrated',?,?,?,?,NULL,?,?,?,'published',?,?,?,?,'migration') ON CONFLICT(id) DO UPDATE SET title=excluded.title, poet=excluded.poet, meter=excluded.meter, body=excluded.body, body_hash=NULL, n_units=excluded.n_units, pub_status='published', updated=excluded.updated WHERE items.by='migration'")
        .bind('it_' + r.id + '_' + k, sec, bid, kind, p.title, p.poet || '', p.meter || '', body, p.verses.length, k, k, txt, r.id, t, t));
    }
    if (st.length) await env.DB.batch(st);
    if (end < total) return { cursor: { i: cur.i, slot: end, phase: 'books' }, inc: 0 };
    // الكتاب اكتمل: تجميع الصيغة القديمة من items دون تحليل JSON، ومطابقتها بايتًا ببايت مع lib.data
    // مواضع زائدة من ترحيل سابق (تقلّص الكتاب في lib): تُؤرشف ولا تُحذف، وتُستثنى من التجميع
    await env.DB.prepare("UPDATE items SET pub_status='archived', updated=? WHERE parent_id=? AND slot >= ? AND by='migration' AND pub_status<>'archived'").bind(t, bid, total).run();
    const rows = (await env.DB.prepare('SELECT title,poet,meter,body FROM items WHERE parent_id=? AND slot IS NOT NULL AND slot < ? ORDER BY slot').bind(bid, total).all()).results || [];
    const arr = '[' + rows.map(x => '{"title":' + JSON.stringify(x.title) + ',"poet":' + JSON.stringify(x.poet) + ',"meter":' + JSON.stringify(x.meter) + ',"verses":' + x.body + '}').join(',') + ']';
    const same = rows.length === total && arr === r.data;
    if (same) {
      const json = legacyHead(r).slice(0, -1) + ',"poems":' + arr + '}';
      await env.DB.prepare('INSERT OR REPLACE INTO lib_render(book_id,version,json,updated) VALUES(?,?,?,?)').bind(r.id, r.t, json, t).run();
      log.push({ t, ok: r.id, n: rows.length });
    } else log.push({ t, err: r.id, why: rows.length !== total ? 'count ' + rows.length + '/' + total : 'content_mismatch' });
    return { cursor: { i: cur.i + 1, slot: 0, phase: 'books' }, inc: 1, fail: same ? 0 : 1 };
  },
};

// /api/lib/book من lib_render عند تفعيل المصدر الجديد (وإن كانت النسخة مطابقة لـ lib.t)، وإلا المسار القديم
async function libBookFromRender(env, id) {
  const src = await siteGet(env, 'lib_source');
  if (!src || src.v !== 'items') return null;
  const r = await env.DB.prepare('SELECT r.json AS json FROM lib_render r JOIN lib l ON l.id=r.book_id AND l.t=r.version WHERE r.book_id=?').bind(id).first();
  return r ? r.json : null;
}

// ---------- صفحة الترحيل (للمالك) ----------
async function adminMigrateJson(url, env, req, ip) {
  if (!env.ADMIN_KEY || !safeEq(url.searchParams.get('key') || '', env.ADMIN_KEY)) return gone();
  const libTables = await tableExists(env, 'items');
  const state = async () => ({
    export: await siteGet(env, 'last_export'), schema: await schemaStatus(env), lib_source: ((await siteGet(env, 'lib_source')) || { v: 'lib' }).v,
    job: (await tableExists(env, 'jobs')) ? await env.DB.prepare("SELECT id,kind,status,total,done,failed,updated,log FROM jobs WHERE kind='migrate-lib' ORDER BY created DESC LIMIT 1").first() : null,
    counts: { lib: (await env.DB.prepare('SELECT COUNT(*) AS n FROM lib').first()).n, items: libTables ? (await env.DB.prepare("SELECT COUNT(*) AS n FROM items WHERE kind<>'book'").first()).n : 0, rendered: libTables ? (await env.DB.prepare('SELECT COUNT(*) AS n FROM lib_render').first()).n : 0 },
  });
  if (!req) return J(await state());
  const o = req.headers.get('origin');
  if (!o || o !== url.origin) return J({ error: 'forbidden' }, 403);
  let b; try { b = await req.json(); } catch (e) { return J({ error: 'bad_input' }, 400); }
  const ex = await siteGet(env, 'last_export'), fresh = !!ex && Date.now() - ex._t < EXPORT_MAX_AGE && ex.ok === true;
  if (b.op === 'schema') {
    if (!fresh) return J({ error: 'need_export' }, 409);
    return J({ applied: await applyMigrations(env, ip), state: await state() });
  }
  if (b.op === 'start') {
    if (!fresh) return J({ error: 'need_export' }, 409);
    if (!libTables) return J({ error: 'need_schema' }, 409);
    if (((await siteGet(env, 'lib_source')) || { v: 'lib' }).v === 'items') return J({ error: 'already_switched' }, 409);
    const j = await jobStart(env, 'migrate-lib', 'owner'); await audit(env, 'migrate:start', j.id, ip); return J({ job: j });
  }
  if (b.op === 'step') { const j = await jobStep(env, String(b.id || '')); return J({ job: { id: j.id, status: j.status, total: j.total, done: j.done, failed: j.failed, log: JSON.parse(j.log || '[]').slice(-5) } }); }
  if (b.op === 'source') {
    const v = b.v === 'items' ? 'items' : 'lib';
    if (v === 'items') {
      const c = await state();
      if (!c.job || c.job.status !== 'done' || c.counts.rendered !== c.counts.lib) return J({ error: 'not_verified' }, 409);
    }
    await siteSet(env, 'lib_source', { v }); await audit(env, 'migrate:source', v, ip);
    return J({ state: await state() });
  }
  return J({ error: 'bad_op' }, 400);
}
async function adminExportMark(url, env, req, ip) {
  if (!env.ADMIN_KEY || !safeEq(url.searchParams.get('key') || '', env.ADMIN_KEY)) return gone();
  const o = req.headers.get('origin'); if (!o || o !== url.origin) return J({ error: 'forbidden' }, 403);
  let b; try { b = await req.json(); } catch (e) { return J({ error: 'bad_input' }, 400); }
  const sha = String(b.sha256 || ''); if (!/^[0-9a-f]{64}$/.test(sha)) return J({ error: 'bad_input' }, 400);
  const v = { ok: b.ok === true, sha256: sha, bytes: Math.max(0, +b.bytes || 0), tables: (b.tables && typeof b.tables === 'object') ? b.tables : {} };
  await siteSet(env, 'last_export', v); await audit(env, 'export:done', sha.slice(0, 16) + (v.ok ? '' : ' (counts mismatch)'), ip);
  return J({ ok: true });
}
function adminMigratePage(url, env) {
  if (!env.ADMIN_KEY || !safeEq(url.searchParams.get('key') || '', env.ADMIN_KEY)) return gone();
  const body = '<p>ترحيل المكتبة إلى البنية الجديدة. <b>إضافي فقط</b>: الجداول القديمة لا تُحذف ولا تُعدَّل، والموقع يبقى على المصدر القديم حتى تفعّل الجديد يدويًا بعد التحقق.</p>' +
    '<div class="c" id="st">…</div>' +
    '<p><button type="button" id="b1">1) إنشاء الجداول الجديدة</button><button type="button" id="b2">2) ترحيل المكتبة والتحقق</button></p>' +
    '<p><button type="button" class="g" id="b3">3) تفعيل المصدر الجديد للكتب</button><button type="button" class="g" id="b4">الرجوع إلى المصدر القديم</button></p><pre id="log"></pre>';
  const script = "var L=document.getElementById('log'),S=document.getElementById('st');function log(t){L.textContent+=t+'\\n';}" +
    "var E={need_export:'يلزم تصدير كامل ناجح خلال آخر 24 ساعة (صفحة «تصدير كامل»).',need_schema:'أنشئ الجداول أولًا.',already_switched:'المصدر الجديد مفعّل؛ لا إعادة ترحيل.',not_verified:'لم يكتمل الترحيل أو لم تتطابق كل الكتب.',forbidden:'طلب مرفوض.'};" +
    "async function api(b){var r=await fetch('/admin/migrate.json',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(b)});var j=await r.json().catch(function(){return{error:'http_'+r.status};});if(j.error)throw new Error(E[j.error]||j.error);return j;}" +
    "async function load(){var s=await (await fetch('/admin/migrate.json',{credentials:'same-origin'})).json();var ex=s.export;" +
    "S.innerHTML='<b>آخر تصدير:</b> '+(ex?new Date(ex._t).toLocaleString()+(ex.ok?' ✔':' ✘ أعداد غير مطابقة')+' · '+ex.sha256.slice(0,16)+'…':'لا يوجد')+'<br><b>الجداول:</b> '+s.schema.map(function(m){return m.id+(m.applied?' ✔':' —')+(m.drift?' ⚠':'');}).join(' · ')+'<br><b>المكتبة:</b> '+s.counts.lib+' كتاب · '+s.counts.items+' مادة مرحَّلة · '+s.counts.rendered+' كتاب متحقَّق منه<br><b>المهمة:</b> '+(s.job?s.job.status+' ('+s.job.done+'/'+s.job.total+', أخطاء '+s.job.failed+')':'—')+'<br><b>مصدر الكتب الحالي:</b> '+(s.lib_source==='items'?'الجديد':'القديم');return s;}" +
    "function busy(v){['b1','b2','b3','b4'].forEach(function(i){document.getElementById(i).disabled=v;});}" +
    "document.getElementById('b1').onclick=async function(){if(!confirm('إنشاء الجداول الجديدة (إضافي، لا يمس البيانات القائمة)؟'))return;busy(true);try{var j=await api({op:'schema'});log('✔ طُبّقت: '+j.applied.join(', '));}catch(e){log('✘ '+e.message);}busy(false);load();};" +
    "document.getElementById('b2').onclick=async function(){if(!confirm('ترحيل المكتبة؟ يمكن إيقافه واستئنافه في أي وقت.'))return;busy(true);try{var j=(await api({op:'start'})).job;log('بدأت المهمة '+j.id);for(var n=0;n<100000;n++){var r;for(var a=0;a<4;a++){try{r=(await api({op:'step',id:j.id})).job;break;}catch(e){log('إعادة المحاولة… '+e.message);await new Promise(function(s){setTimeout(s,1500*(a+1));});}}if(!r)throw new Error('توقف بعد 4 محاولات؛ أعد الضغط للاستئناف.');" +
    "(r.log||[]).forEach(function(x){if(x.err)log('✘ '+x.err+': '+x.why);});S.firstChild&&(S.dataset.p=r.done+'/'+r.total);if(r.status!=='running'){log(r.status==='done'?'✔ اكتمل: '+r.done+' كتاب، كلها مطابقة بايتًا ببايت.':'✘ انتهت مع أخطاء: '+r.failed);break;}if(n%5===0)await load();}}catch(e){log('✘ '+e.message);}busy(false);load();};" +
    "document.getElementById('b3').onclick=async function(){if(!confirm('تقديم الكتب من البنية الجديدة؟ (الرجوع متاح بزر واحد)'))return;try{await api({op:'source',v:'items'});log('✔ فُعّل المصدر الجديد');}catch(e){log('✘ '+e.message);}load();};" +
    "document.getElementById('b4').onclick=async function(){try{await api({op:'source',v:'lib'});log('✔ رجوع إلى المصدر القديم');}catch(e){log('✘ '+e.message);}load();};load();";
  return adminShell(url.searchParams.get('key') || '', 'ترحيل قاعدة البيانات', body, script);
}
// =====================================================================

const handler = {
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    const p = url.pathname;
    const ip = req.headers.get('CF-Connecting-IP') || 'unknown';
    // ---- الإدارة: تسجيل الدخول والخروج، وتحويل الروابط القديمة ?key= إلى ملف تعريف
    if (p === '/admin/login') {
      if (!env.ADMIN_KEY) return gone();
      await init(env);
      if (await admBlocked(env, ip)) return new Response('Too many attempts', { status: 429 });
      if (req.method !== 'POST') return admLoginPage('');
      let k = ''; try { k = String((await req.formData()).get('key') || ''); } catch (e) { /* */ }
      if (!safeEq(k, env.ADMIN_KEY)) { await admFail(env, ip); return admLoginPage('مفتاح غير صحيح.'); }
      await audit(env, 'login', 'admin', ip);
      return new Response(null, { status: 303, headers: { location: '/admin', 'set-cookie': admSetCookie(await admToken(env)), 'cache-control': 'no-store' } });
    }
    if (p === '/admin/logout') return new Response(null, { status: 303, headers: { location: '/', 'set-cookie': 'adm=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0' } });
    if (p.startsWith('/admin') || p === '/health') {
      const qk = url.searchParams.get('key') || '';
      if (qk && env.ADMIN_KEY && req.method === 'GET' && ADM_HTML.includes(p)) {
        if (safeEq(qk, env.ADMIN_KEY)) { url.searchParams.delete('key'); return new Response(null, { status: 303, headers: { location: url.pathname + url.search, 'set-cookie': admSetCookie(await admToken(env)), 'cache-control': 'no-store', 'referrer-policy': 'no-referrer' } }); }
      } else if (!qk && await admCookieOk(req, env)) url.searchParams.set('key', env.ADMIN_KEY); // تُمرَّر داخلياً فقط
      else if (!qk && req.method === 'GET' && ADM_HTML.includes(p) && env.ADMIN_KEY) return new Response(null, { status: 303, headers: { location: '/admin/login' } });
    }
    const adm = async fn => { try { await init(env); if (await admBlocked(env, ip)) return new Response('Too many attempts', { status: 429 }); const r = await fn(); if (r.status === 404) await admFail(env, ip); return r; } catch (e) { return new Response('error', { status: 500 }); } };
    if (req.method === 'GET') {
      if (p === '/' || p === '/index.html') {
        let html = INDEX;
        if (env.ASSETS) { try { const ar = await env.ASSETS.fetch(new Request(url.origin + '/ui.txt')); if (ar.ok) { const tx = await ar.text(); if (tx.includes('/api/verses')) html = tx; } } catch (e) { /* */ } }
        try { await init(env); const r = await env.DB.prepare('SELECT val,t FROM site WHERE name=?').bind('index').first(); if (r && r.val && r.t > BUILD) html = r.val; } catch (e) { /* النسخة المضمّنة */ }
        // روابط التطبيق القابل للتثبيت (PWA) إن لم تكن في الواجهة
        if (!/rel=["']?manifest/i.test(html)) html = html.replace('</head>', '<link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><meta name="theme-color" content="#17110C"></head>');
        const res = page(html, 'text/html; charset=utf-8'); res.headers.set('cache-control', 'no-cache'); return res;
      }
      if (p === '/manifest.webmanifest') return page(MANIFEST, 'application/manifest+json; charset=utf-8');
      if (p === '/sw.js') return page(SW, 'application/javascript; charset=utf-8');
      if (p === '/icon.svg') return page(ICON, 'image/svg+xml');
      if (p === '/privacy' || p === '/terms') return page(PRIVACY, 'text/html; charset=utf-8');
      if (p === '/privacy-en' || p === '/terms-en') return page(PRIVACY_EN, 'text/html; charset=utf-8');
      if (p === '/icon-maskable-512.png') return png(ICONM);
      if (p === '/icon-192.png') return png(ICON192);
      if (p === '/icon-512.png') return png(ICON512);
      if (p === '/apple-touch-icon.png') return png(ICON180);
      if (p === '/icon-32.png') return png(ICON32);
      if (p === '/vendor/pdf-lib.min.js') return new Response(PDFLIB, { headers: { 'content-type': 'application/javascript; charset=utf-8', 'cache-control': 'public, max-age=31536000, immutable', 'x-content-type-options': 'nosniff' } });
      if (p === '/api/config') return J({ sitekey: env.TURNSTILE_SITEKEY || '', source: env.SHAMELA_ON === '1', accounts: !!sessSecret(env), mybooks: !!sessSecret(env), pdfPages: +env.USER_PDF_PAGES || 60 });
      if (p === '/api/lib' || p === '/api/lib/book') { try { await init(env); return await libApi(url, env); } catch (e) { return J({ error: 'server' }, 500); } }
      if (p === '/admin/ui') return adm(() => adminUi(url, env, undefined, ip));
      if (p === '/admin/lib') return adm(() => adminLib(url, env, undefined, ip));
      if (p === '/admin/users') return adm(() => adminUsers(url, env, undefined, ip));
      if (p === '/admin/backup') return adm(() => adminBackup(url, env));
      if (p === '/admin/export') return adm(() => adminExportPage(url, env));
      if (p === '/admin/export.json') return adm(() => adminExportJson(url, env));
      if (p === '/admin/migrate') return adm(() => adminMigratePage(url, env));
      if (p === '/admin/migrate.json') return adm(() => adminMigrateJson(url, env, undefined, ip));
      if (p === '/admin/import') return adm(() => adminImport(url, env));
      if (p === '/admin' || p === '/admin.json') return adm(() => handleAdmin(url, env));
      if (p === '/admin/source') {
        if (!env.ADMIN_KEY || !safeEq(url.searchParams.get('key') || '', env.ADMIN_KEY)) return gone();
        try { await init(env); const v = String(url.searchParams.get('verse') || '').slice(0, 300); const raw = await claudeMcp(env, sourcePrompt(v)); return J({ raw: raw.slice(0, 1500), parsed: parseSource(raw) }); } catch (e) { return J({ error: (e && e.error) || 'server' }, (e && e.status) || 500); }
      }
      if (p === '/health') {
        let db = false, why = '';
        if (!env.DB) why = 'no_binding: لم يُربط D1 باسم DB';
        else { try { await init(env); await env.DB.prepare('SELECT 1').first(); db = true; } catch (e) { why = String((e && e.message) || e).slice(0, 120); } }
        const warn = [];
        if (!env.SESSION_SECRET) warn.push('SESSION_SECRET absent : les sessions dépendent de ADMIN_KEY/TURNSTILE_SECRET');
        if (!env.SALT) warn.push('SALT absent');
        if (env.ADMIN_KEY && env.ADMIN_KEY.length < 24) warn.push('ADMIN_KEY trop courte (24 caractères conseillés)');
        if (!env.TURNSTILE_SECRET) warn.push('Turnstile désactivé : seul le plafond mensuel protège contre les abus');
        const out = { ok: db && !!env.ANTHROPIC_API_KEY, db, key: !!env.ANTHROPIC_API_KEY, accounts: !!sessSecret(env), why, version: 3, warn };
        if (db && env.ADMIN_KEY && safeEq(url.searchParams.get('key') || '', env.ADMIN_KEY)) {
          const le = await env.DB.prepare("SELECT val,t FROM site WHERE name='last_error'").first();
          out.last_error = le ? { ...JSON.parse(le.val), at: new Date(le.t).toISOString() } : null;
          out.model = env.MODEL || 'claude-sonnet-5-5';
        }
        return J(out);
      }
      return new Response('Not found', { status: 404 });
    }
    if (req.method === 'POST') {
      if (p === '/admin/import') return adm(() => adminImport(url, env, req));
      if (p === '/admin/migrate.json') return adm(() => adminMigrateJson(url, env, req, ip));
      if (p === '/admin/export-mark') return adm(() => adminExportMark(url, env, req, ip));
      if (p === '/admin/ui') return adm(() => adminUi(url, env, req, ip));
      if (p === '/admin/lib') return adm(() => adminLib(url, env, req, ip));
      if (p === '/admin/users') return adm(() => adminUsers(url, env, req, ip));
      if (p === '/admin/pdf') { try { await init(env); if (await admBlocked(env, ip)) return new Response('Too many attempts', { status: 429 }); const pr = handlePdf(req, env, ctx, url); if (pr.status === 404) await admFail(env, ip); else await audit(env, 'pdf', 'extract', ip); return pr; } catch (e) { return new Response('error', { status: 500 }); } }
      const isAuth = p.startsWith('/api/auth/'), isMy = p.startsWith('/api/my/');
      if (isAuth || isMy || p === '/api/sync' || p === '/api/verses' || p === '/api/info' || p === '/api/feedback' || p === '/api/verify' || p === '/api/source') {
        // نقبل الطلبات من نفس الموقع فقط
        const origin = req.headers.get('origin'), sfs = req.headers.get('sec-fetch-site');
        if ((origin && origin !== url.origin) || (sfs && sfs !== 'same-origin' && sfs !== 'none')) return J({ error: 'forbidden' }, 403);
        const len = +req.headers.get('content-length') || 0;
        if (len > (p === '/api/my/pdf' ? 9600000 : p === '/api/my/put' ? 900000 : p === '/api/sync' ? 320000 : 20000)) return J({ error: 'bad_input' }, 413);
        try {
          await init(env);
          if (Math.random() < 0.02) {
            ctx.waitUntil(env.DB.batch([
              env.DB.prepare('DELETE FROM rl WHERE t < ?').bind(Date.now() - 3 * 86400000),
              env.DB.prepare('DELETE FROM cache WHERE t < ?').bind(Date.now() - 90 * 86400000),
              env.DB.prepare('DELETE FROM usage WHERE t < ?').bind(Date.now() - 30 * 86400000),
              env.DB.prepare('DELETE FROM feedback WHERE t < ?').bind(Date.now() - 180 * 86400000),
              env.DB.prepare('DELETE FROM audit WHERE t < ?').bind(Date.now() - 365 * 86400000),
            ]).catch(() => {}));
          }
          if (isAuth) return await handleAuth(req, env, ip, p.slice(10));
          if (isMy) return await handleMy(req, env, ctx, ip, p.slice(8));
          if (p === '/api/sync') return await handleSync(req, env);
          if (p === '/api/feedback') return await handleFeedback(req, env, ip);
          if (p === '/api/verify') return await handleVerify(req, env, ip);
          if (p === '/api/source') return await handleSource(req, env, ip);
          return p === '/api/verses' ? await handleVerses(req, env, ip) : await handleInfo(req, env, ip);
        } catch (e) {
          if (e && e.status) return J({ error: e.error }, e.status);
          return J({ error: 'server' }, 500);
        }
      }
    }
    return new Response('Method not allowed', { status: 405 });
  },
};

export default {
  async fetch(req, env, ctx) {
    try { return secure(await handler.fetch(req, env, ctx)); } catch (e) { return secure(new Response('error', { status: 500 })); }
  },
};
